        else lps[i++] = 0;
    }
    return lps;
}
int kmp(const string& t, const string& p) {
    auto lps = buildLps(p); int j = 0;
    for (int i = 0; i < (int)t.size(); ++i) {
        while (j && t[i] != p[j]) j = lps[j-1];
        if (t[i] == p[j]) ++j;
        if (j == (int)p.size()) return i - j + 1;  // match start
    }
    return -1;
}

def build_lps(p):
    lps = [0] * len(p)
    length, i = 0, 1
    while i < len(p):
        if p[i] == p[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    return lps

def kmp(t, p):
    lps = build_lps(p)
    j = 0
    for i in range(len(t)):
        while j and t[i] != p[j]:
            j = lps[j - 1]
        if t[i] == p[j]:
            j += 1
        if j == len(p):
            return i - j + 1        # match start index
    return -1

class Solution {
public:
    int strStr(string h, string n) {
        if (n.empty()) return 0;
        int m = n.size();
        vector<int> lps(m, 0);
        for (int i = 1, len = 0; i < m; ) {
            if (n[i] == n[len]) lps[i++] = ++len;
            else if (len) len = lps[len - 1];
            else lps[i++] = 0;
        }
        for (int i = 0, j = 0; i < (int)h.size(); ) {
            if (h[i] == n[j]) { i++; j++; if (j == m) return i - m; }
            else if (j) j = lps[j - 1];
            else i++;
        }
        return -1;
    }
};

class Solution:
    def strStr(self, h: str, n: str) -> int:
        if not n:
            return 0
        m = len(n)
        lps = [0] * m
        length = 0
        i = 1
        while i < m:
            if n[i] == n[length]:
                length += 1; lps[i] = length; i += 1
            elif length:
                length = lps[length - 1]
            else:
                lps[i] = 0; i += 1
        i = j = 0
        while i < len(h):
            if h[i] == n[j]:
                i += 1; j += 1
                if j == m:
                    return i - m
            elif j:
                j = lps[j - 1]
            else:
                i += 1
        return -1

class Solution {
public:
    int repeatedStringMatch(string a, string b) {
        string s = a;
        int count = 1;
        while ((int)s.size() < (int)b.size()) { s += a; count++; }
        if (s.find(b) != string::npos) return count;
        s += a;
        if (s.find(b) != string::npos) return count + 1;
        return -1;
    }
};

class Solution:
    def repeatedStringMatch(self, a: str, b: str) -> int:
        s = a
        count = 1
        while len(s) < len(b):
            s += a; count += 1
        if b in s:
            return count
        if b in s + a:
            return count + 1
        return -1

class Solution {
public:
    string shortestPalindrome(string s) {
        string rev(s.rbegin(), s.rend());
        string t = s + "#" + rev;
        int m = t.size();
        vector<int> lps(m, 0);
        for (int i = 1, len = 0; i < m; ) {
            if (t[i] == t[len]) lps[i++] = ++len;
            else if (len) len = lps[len - 1];
            else lps[i++] = 0;
        }
        int pal = lps[m - 1];
        return rev.substr(0, s.size() - pal) + s;
    }
};

class Solution:
    def shortestPalindrome(self, s: str) -> str:
        rev = s[::-1]
        t = s + "#" + rev
        m = len(t)
        lps = [0] * m
        length = 0
        for i in range(1, m):
            while length and t[i] != t[length]:
                length = lps[length - 1]
            if t[i] == t[length]:
                length += 1
            lps[i] = length
        pal = lps[-1]
        return rev[:len(s) - pal] + s

class Solution {
public:
    string longestPrefix(string s) {
        int n = s.size();
        vector<int> lps(n, 0);
        for (int i = 1, len = 0; i < n; ) {
            if (s[i] == s[len]) lps[i++] = ++len;
            else if (len) len = lps[len - 1];
            else lps[i++] = 0;
        }
        return s.substr(0, lps[n - 1]);
    }
};

class Solution:
    def longestPrefix(self, s: str) -> str:
        n = len(s)
        lps = [0] * n
        length = 0
        for i in range(1, n):
            while length and s[i] != s[length]:
                length = lps[length - 1]
            if s[i] == s[length]:
                length += 1
            lps[i] = length
        return s[:lps[-1]]

class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        if (p.size() > s.size()) return {};
        vector<int> need(26, 0), win(26, 0); vector<int> res;
        for (char c : p) need[c - 'a']++;
        int k = p.size();
        for (int i = 0; i < (int)s.size(); i++) {
            win[s[i] - 'a']++;
            if (i >= k) win[s[i - k] - 'a']--;
            if (i >= k - 1 && win == need) res.push_back(i - k + 1);
        }
        return res;
    }
};

class Solution:
    def findAnagrams(self, s: str, p: str) -> list[int]:
        if len(p) > len(s):
            return []
        need = [0] * 26
        win = [0] * 26
        for c in p:
            need[ord(c) - 97] += 1
        k = len(p)
        res = []
        for i, c in enumerate(s):
            win[ord(c) - 97] += 1
            if i >= k:
                win[ord(s[i - k]) - 97] -= 1
            if i >= k - 1 and win == need:
                res.append(i - k + 1)
        return res
